/* Skip link */
.skip-link {
  position: absolute;
  left: 0.5rem;
  top: -40px;
  background: var(--accent);
  color: #1a1300;
  padding: 0.5rem 0.875rem;
  border-radius: 6px;
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 0.5rem;
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

/* Header */
.site-header {
  border-bottom: 1px solid var(--border);
  background: rgba(14, 15, 19, 0.6);
  backdrop-filter: blur(8px);
}
.site-header .wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-top: 1rem;
  padding-bottom: 1rem;
}
.brand {
  margin: 0;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--text);
}
.site-header nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 1.25rem;
}
.site-header nav a {
  color: var(--text-muted);
  text-decoration: none;
  font-weight: 500;
  padding: 0.25rem 0.25rem;
  border-radius: 4px;
}
.site-header nav a:hover { color: var(--text); }
.site-header nav a[aria-current="page"] { color: var(--accent); }
.site-header nav a:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
}

/* Main */
main {
  padding-top: 3rem;
  padding-bottom: 4rem;
}
h1 {
  font-size: clamp(2rem, 4vw + 1rem, 2.75rem);
  margin: 0 0 0.5rem;
  letter-spacing: -0.02em;
}
.lede {
  margin: 0 0 2.25rem;
  color: var(--text-muted);
  font-size: 1.0625rem;
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* FAQ list */
.faq {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.example {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color 0.2s ease, background 0.2s ease;
}
.example:hover { border-color: var(--border-strong); }
.example:has(.faq-trigger[aria-expanded="true"]) {
  border-color: var(--border-strong);
  background: var(--bg-elevated-hover);
}

.example h3 {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
}

.faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.125rem 1.25rem;
  background: transparent;
  border: 0;
  color: var(--text);
  font: inherit;
  font-size: 1.0625rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  border-radius: var(--radius);
}
.faq-trigger:hover { color: var(--accent-strong); }
.faq-trigger:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}

.faq-label { flex: 1; }

.faq-icon {
  flex: none;
  width: 1.25rem;
  height: 1.25rem;
  position: relative;
  border: 1px solid var(--border-strong);
  border-radius: 50%;
  transition: transform 0.2s ease, border-color 0.2s ease, background 0.2s ease;
}
.faq-icon::before,
.faq-icon::after {
  content: "";
  position: absolute;
  background: currentColor;
  border-radius: 1px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.faq-icon::before { width: 0.625rem; height: 2px; }
.faq-icon::after  { width: 2px; height: 0.625rem; transition: transform 0.2s ease; }

.faq-trigger[aria-expanded="true"] .faq-icon {
  border-color: var(--accent);
  background: rgba(244, 180, 90, 0.12);
  color: var(--accent);
}
.faq-trigger[aria-expanded="true"] .faq-icon::after {
  transform: translate(-50%, -50%) scaleY(0);
}

.details {
  padding: 0 1.25rem 1.25rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
}
.details p { margin: 1rem 0 0; }

/* Footer */
.site-footer {
  border-top: 1px solid var(--border);
  padding: 1.5rem 0;
  color: var(--text-muted);
  font-size: 0.9375rem;
}
.site-footer a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.site-footer a:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 2px;
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

/* Forced colors (Windows High Contrast) */
@media (forced-colors: active) {
  .example { border-color: CanvasText; }
  .faq-trigger:focus-visible { outline-color: Highlight; }
  .faq-icon { border-color: CanvasText; }
}
