+  align-items: center;
+  justify-content: space-between;
+  gap: 1rem;
+  padding: 1.125rem 1.25rem;
+  background: transparent;
+  border: 0;
+  color: var(--text);
+  font: inherit;
+  font-size: 1.0625rem;
+  font-weight: 600;
+  text-align: left;
+  cursor: pointer;
+  border-radius: var(--radius);
+}
+.faq-trigger:hover { color: var(--accent-strong); }
+.faq-trigger:focus-visible {
+  outline: 2px solid var(--focus);
+  outline-offset: -2px;
+}
+
+.faq-label { flex: 1; }
+
+.faq-icon {
+  flex: none;
+  width: 1.25rem;
+  height: 1.25rem;
